#include "core/trace_quality.hpp"
#include "core/abif.hpp"
#include "core/session.hpp"
#include "abif_fixture.hpp"
#include <algorithm>
#include <functional>
#include <iostream>
#include <random>
#include <sstream>
#include <stdexcept>
using namespace kleiotide;
namespace {
void require(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
template<class F>void rejects(F action){bool threw=false;try{action();}catch(const std::exception&){threw=true;}require(threw,"Expected rejection");}
Record traced(std::string bases,std::vector<std::uint8_t> q){std::istringstream input(test::synthetic_abif(bases));auto record=read_abif(input,"trace","missing.ab1");auto evidence=std::make_shared<Chromatogram>(*record.trace->original);evidence->quality=std::move(q);auto link=std::make_shared<TraceLink>(*record.trace);link->original=evidence;record.trace=link;return record;}
QualitySettings trim(unsigned q=25,unsigned window=3){return {QualityOperation::TrimEnds,QualityScope::Selected,q,window,false};}
QualitySettings toN(unsigned q=20){return {QualityOperation::CallsToN,QualityScope::Selected,q,1,false};}
}
int main(){int passed=0,failed=0;auto run=[&](const char* name,const std::function<void()>& test){try{test();++passed;std::cout<<"PASS "<<name<<'\n';}catch(const std::exception& e){++failed;std::cerr<<"FAIL "<<name<<": "<<e.what()<<'\n';}};
run("Window means retain exact terminal interval and atomic undo/redo",[]{Document d;d.load({traced("ACGTACGTAC",{0,0,30,30,30,30,30,30,0,0})});const auto link=d.sequence(1).trace;auto p=plan_trace_quality(d,trim(),{1});require(p.changedRows==1&&p.changedSymbols==4&&p.rows[0].trimLeft==2&&p.rows[0].trimRight==2&&p.rows[0].keepBegin==2&&p.rows[0].keepEnd==8,"Exact first/last passing windows");apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="~~GTACGT~~"&&d.sequence(1).trace->originalCalls==std::vector<std::int32_t>({2,3,4,5,6,7}),"Columns retained and only removed calls lose anchors");require(d.sequence(1).trace->original==link->original,"Evidence shared unchanged");d.undo();require(d.sequence(1).symbols.text()=="ACGTACGTAC"&&d.sequence(1).trace==link&&!d.can_undo(),"One undo restores exact trace object");d.redo();require(d.sequence(1).symbols.text()=="~~GTACGT~~","Redo restores trim");});
run("Equality passes trimming but is not converted to N",[]{Document d;d.load({traced("ACGTAC",{0,20,20,20,20,0})});auto p=plan_trace_quality(d,trim(20,2),{1});apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="~CGTA~","Mean equal to threshold passes");d.undo();p=plan_trace_quality(d,toN(20),{1});apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="NCGTAN","Only strictly lower calls convert");});
run("Internal low-quality islands are retained",[]{Document d;d.load({traced("ACGTACGTACGT",{0,30,30,30,0,0,0,0,30,30,30,0})});auto p=plan_trace_quality(d,trim(25,2),{1});apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="~CGTACGTACG~"&&p.changedSymbols==2,"One interval spans first and last passing windows");});
run("Windows count residues and preserve existing gap states",[]{Document d;d.load({traced("ACGTAC",{0,30,30,30,30,0})});d.replace(1,0,6,"-A~CG-T~A-C-");const auto before=d.sequence(1).trace;auto p=plan_trace_quality(d,trim(25,2),{1});apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="-~~CG-T~A-~-"&&d.columns()==12,"No gap is counted or shifted and locked gaps survive");require(d.sequence(1).trace->original==before->original,"Evidence intact");});
run("No passing window and short rows are never erased",[]{Document d;d.load({traced("ACGT",{1,2,3,4})});for(const auto settings:{trim(20,2),trim(0,5)}){auto p=plan_trace_quality(d,settings,{1});require(p.edits.empty()&&p.rows[0].keepEnd==4,"No destructive whole-row trim");apply_trace_quality(d,p);}require(d.sequence(1).symbols.text()=="ACGT"&&!d.can_undo(),"No-op adds no history");});
run("Absent Q is distinct from measured zero",[]{Document missing;missing.load({traced("ACGT",{})});for(const auto settings:{trim(1,1),toN(1)}){auto p=plan_trace_quality(missing,settings,{1});require(p.rows[0].missingQ==4&&p.rows[0].scored==0&&!p.changedRows,"Absent Q protected");}Document zeros;zeros.load({traced("ACGT",{0,0,0,0})});auto p=plan_trace_quality(zeros,toN(1),{1});apply_trace_quality(zeros,p);require(zeros.sequence(1).symbols.text()=="NNNN","Measured Q0 remains usable evidence");});
run("Manual substitutions are protected unless original Q explicitly enabled",[]{Document d;d.load({traced("ACGTACGT",{0,0,30,30,30,30,0,0})});d.replace(1,0,1,"T");auto p=plan_trace_quality(d,trim(25,2),{1});require(p.rows[0].protectedEdited==1&&p.rows[0].keepBegin==0,"Edited terminal call anchors retained interval");apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="TCGTAC~~","Protected call and contiguous interval remain");d.undo();auto settings=trim(25,2);settings.useOriginalQForEdited=true;p=plan_trace_quality(d,settings,{1});apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="~~GTAC~~"&&p.rows[0].protectedEdited==0,"Original Q may explicitly evaluate edited call");d.undo();p=plan_trace_quality(d,toN(20),{1});require(p.changedSymbols==3,"Default N operation protects substituted base");settings=toN(20);settings.useOriginalQForEdited=true;p=plan_trace_quality(d,settings,{1});require(p.changedSymbols==4,"Explicit original Q includes substituted base");});
run("Inserted calls always stay protected",[]{Document d;d.load({traced("ACGTAC",{0,30,30,30,30,0})});d.replace(1,0,0,"G");auto settings=trim(25,2);settings.useOriginalQForEdited=true;auto p=plan_trace_quality(d,settings,{1});require(p.rows[0].missingQ==1&&p.rows[0].keepBegin==0,"Inserted base has no original Q even in inclusion mode");apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="GACGTA~"&&d.sequence(1).trace->originalCalls.front()==-1,"Insertion survives with synthetic provenance");});
run("Reverse orientation evaluates corresponding original qualities",[]{Document d;d.load({traced("ACGTAA",{5,30,30,30,30,0})});d.transform({1},Document::Transform::ReverseComplement);const auto original=d.sequence(1).trace->original;auto p=plan_trace_quality(d,toN(),{1});apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="NTACGN"&&d.sequence(1).trace->reversed&&d.sequence(1).trace->original==original,"Reversed calls follow reversed mapping");d.undo();p=plan_trace_quality(d,trim(25,2),{1});apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="~TACG~"&&d.sequence(1).trace->originalCalls==std::vector<std::int32_t>({4,3,2,1}),"Reversed trace trimming preserves correct anchors");});
run("Case is retained and existing N does not inflate changed count",[]{Document d;d.load({traced("ACGT",{0,30,30,0})});d.transform({1},Document::Transform::Lowercase);auto p=plan_trace_quality(d,toN(),{1});apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="ncgn"&&p.rows[0].protectedEdited==0,"Case-only edits are not substitutions");Document n;n.load({traced("NA",{0,0})});p=plan_trace_quality(n,toN(),{1});require(p.changedSymbols==1,"Existing N stays unchanged");});
run("Scope is explicit and ineligible types are reported",[]{Document d;d.load({traced("ACGT",{0,0,0,0}),{"plain","ACGT"},{"mask","0123",RowKind::Mask},{"protein","ACGT",RowKind::Protein}});auto p=plan_trace_quality(d,toN());require(p.rows.empty()&&!p.changedRows,"No selected names never means all");p=plan_trace_quality(d,toN(),{1,2,3,4});require(p.changedRows==1&&p.ignoredRows==3&&p.eligibleRows==1,"Mixed selected rows reported");auto settings=toN();settings.scope=QualityScope::AllTraces;p=plan_trace_quality(d,settings);apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="NNNN"&&d.sequence(2).symbols.text()=="ACGT"&&d.sequence(3).symbols.text()=="0123"&&d.sequence(4).kind==RowKind::Protein,"All traces does not edit unlinked, masks or proteins");});
run("Multirow Apply is one command preserving groups and immutable evidence",[]{Document d;d.load({traced("ACGT",{0,30,30,0}),traced("TGCA",{0,30,30,0})});d.apply_groups({{1,"Group",0x0072b2}},{{1,1},{2,1}});const auto evidence=d.sequence(1).trace->original;const auto baseline=d.state_id();auto settings=trim(25,2);settings.scope=QualityScope::AllTraces;auto p=plan_trace_quality(d,settings);apply_trace_quality(d,p);require(p.changedRows==2&&d.sequence(1).symbols.text()=="~CG~"&&d.sequence(2).symbols.text()=="~GC~"&&d.sequence(2).groupId==1,"Rows and groups preserved");require(evidence==d.sequence(1).trace->original&&evidence->quality==std::vector<std::uint8_t>({0,30,30,0}),"Original values not rewritten");d.undo();require(d.state_id()==baseline&&d.sequence(1).symbols.text()=="ACGT"&&d.sequence(2).symbols.text()=="TGCA","Single undo for both rows");d.redo();std::ostringstream output(std::ios::binary);write_session(output,d);std::istringstream input(output.str(),std::ios::binary);auto reopened=read_session(input);require(reopened.document.sequence(1).symbols.text()=="~CG~"&&reopened.document.sequence(1).trace->original->quality==evidence->quality,"Session retains trim and original Q");});
run("Changed calls keep original anchor but gain no invented current quality",[]{Document d;d.load({traced("ACGT",{0,30,30,0})});const auto link=d.sequence(1).trace;auto p=plan_trace_quality(d,toN(),{1});apply_trace_quality(d,p);const auto position=trace_position(d.sequence(1),0);require(position.edited&&!position.quality&&position.originalCall==0&&d.sequence(1).trace->originalCalls==link->originalCalls,"Edited N is linked evidence, not measured N quality");});
run("Stale plans, wrong documents and invalid settings reject atomically",[]{Document d;d.load({traced("ACGT",{0,0,0,0})});auto p=plan_trace_quality(d,toN(),{1});Document other;other.load({traced("ACGT",{0,0,0,0})});rejects([&]{apply_trace_quality(other,p);});d.rename({{1,"new"}});rejects([&]{apply_trace_quality(d,p);});for(auto bad:{QualitySettings{QualityOperation::TrimEnds,QualityScope::Selected,256,1,false},trim(20,0),trim(20,10001)})rejects([&]{plan_trace_quality(d,bad,{1});});rejects([&]{plan_trace_quality(d,toN(),{1,1});});rejects([&]{plan_trace_quality(d,toN(),{999});});require(d.sequence(1).symbols.text()=="ACGT"&&other.sequence(1).symbols.text()=="ACGT","Rejected plans never partially edit");});
run("Cancellation leaves source and history unchanged",[]{Document d;d.load({traced("ACGT",{0,0,0,0})});const auto state=d.state_id();rejects([&]{plan_trace_quality(d,toN(),{1},[]{return true;});});require(d.state_id()==state&&!d.can_undo(),"Cancelled preview is read-only");});
run("Sliding-window result agrees with independent exhaustive reference",[]{std::mt19937 random(418);for(unsigned trial=0;trial<150;++trial){const unsigned count=8+random()%20,width=1+random()%8,threshold=random()%41;std::vector<std::uint8_t> q(count);for(auto& value:q)value=static_cast<std::uint8_t>(random()%41);Document d;d.load({traced(std::string(count,'A'),q)});std::size_t first=count,last=0;for(unsigned start=0;start+width<=count;++start){unsigned sum=0;for(unsigned j=0;j<width;++j)sum+=q[start+j];if(sum>=threshold*width){first=std::min(first,static_cast<std::size_t>(start));last=start+width;}}auto p=plan_trace_quality(d,trim(threshold,width),{1});std::string expected(count,'A');if(first<count){std::fill(expected.begin(),expected.begin()+static_cast<std::ptrdiff_t>(first),'~');std::fill(expected.begin()+static_cast<std::ptrdiff_t>(last),expected.end(),'~');}apply_trace_quality(d,p);require(d.sequence(1).symbols.text()==expected,"Reference interval agreement");}});
run("Earlier N cleanup remains edited until original-Q inclusion is chosen",[]{Document d;d.load({traced("ACGTAC",{0,30,30,30,30,0})});auto p=plan_trace_quality(d,toN(),{1});apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="NCGTAN","Initial N cleanup");p=plan_trace_quality(d,trim(25,2),{1});require(!p.changedRows&&p.rows[0].protectedEdited==2,"Previous substitutions are protected too");auto settings=trim(25,2);settings.useOriginalQForEdited=true;p=plan_trace_quality(d,settings,{1});apply_trace_quality(d,p);require(d.sequence(1).symbols.text()=="~CGTA~","Explicit original evidence permits trimming previously masked ends");});
std::cout<<passed<<" passed; "<<failed<<" failed\n";return failed?1:0;}
